 11→pub fn format_unix_ts(ts_str: &str) -> String {
 12→    let secs: i64 = match ts_str.split('.').next() {
 13→        Some(s) => s.parse().unwrap_or(0),
 14→        None => 0,
 15→    };
 16→
 17→    let time_of_day = secs.rem_euclid(86400);
 18→    let hours = time_of_day / 3600;
 19→    let minutes = (time_of_day % 3600) / 60;
 20→    let seconds = time_of_day % 60;
 21→
 22→    // Howard Hinnant's civil_from_days algorithm
 23→    let z = secs.div_euclid(86400) + 719468;
 24→    let era = if z >= 0 { z } else { z - 146096 } / 146097;
 25→    let doe = z - era * 146097;
 26→    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
 27→    let y = yoe + era * 400;
 28→    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
 29→    let mp = (5 * doy + 2) / 153;
 30→    let d = doy - (153 * mp + 2) / 5 + 1;
 31→    let m = if mp < 10 { mp + 3 } else { mp - 9 };
 32→    let y = if m <= 2 { y + 1 } else { y };
 33→
 34→    format!(
 35→        "{:04}-{:02}-{:02} {:02}:{:02}:{:02}",
 36→        y, m, d, hours, minutes, seconds
 37→    )
 38→}
