 40→pub fn extract_messages(response: &JsonValue) -> Result<Vec<SlackMessage>, SlkError> {
 41→    let ok = response
 42→        .get("ok")
 43→        .and_then(|v| v.as_bool())
 44→        .ok_or(SlkError::from("missing 'ok' field in response"))?;
 45→
 46→    if !ok {
 47→        let error = response
 48→            .get("error")
 49→            .and_then(|v| v.as_str())
 50→            .unwrap_or("unknown error");
 51→        let needed = response.get("needed").and_then(|v| v.as_str());
 52→        let provided = response.get("provided").and_then(|v| v.as_str());
 53→        let mut msg = format!("Slack API error: {}", error);
 54→        if let Some(needed) = needed {
 55→            msg.push_str(&format!("\n  needed scope: {}", needed));
 56→        }
 57→        if let Some(provided) = provided {
 58→            msg.push_str(&format!("\n  provided scopes: {}", provided));
 59→        }
 60→        return Err(SlkError::from(msg));
 61→    }
 62→
 63→    let messages = response
 64→        .get("messages")
 65→        .and_then(|v| v.as_array())
 66→        .ok_or(SlkError::from("missing 'messages' array in response"))?;
 67→
 68→    let mut result = Vec::new();
 69→    for msg in messages {
 70→        let user = msg
 71→            .get("user")
 72→            .and_then(|v| v.as_str())
 73→            .or_else(|| msg.get("username").and_then(|v| v.as_str()))
 74→            .or_else(|| msg.get("bot_id").and_then(|v| v.as_str()))
 75→            .unwrap_or("unknown")
 76→            .to_string();
 77→
 78→        let text = msg
 79→            .get("text")
 80→            .and_then(|v| v.as_str())
 81→            .unwrap_or("")
 82→            .to_string();
 83→
 84→        let ts = msg
 85→            .get("ts")
 86→            .and_then(|v| v.as_str())
 87→            .unwrap_or("0")
 88→            .to_string();
 89→
 90→        result.push(SlackMessage { user, text, ts });
 91→    }
 92→
 93→    Ok(result)
 94→}
