 96→pub fn resolve_user_name(response: &JsonValue) -> Option<String> {
 97→    let user = response.get("user")?;
 98→
 99→    let profile = user.get("profile");
100→    if let Some(profile) = profile {
101→        if let Some(display_name) = profile.get("display_name").and_then(|v| v.as_str()) {
102→            if !display_name.is_empty() {
103→                return Some(display_name.to_string());
104→            }
105→        }
106→    }
107→
108→    if let Some(real_name) = user.get("real_name").and_then(|v| v.as_str()) {
109→        if !real_name.is_empty() {
110→            return Some(real_name.to_string());
111→        }
112→    }
113→
114→    if let Some(name) = user.get("name").and_then(|v| v.as_str()) {
115→        if !name.is_empty() {
116→            return Some(name.to_string());
117→        }
118→    }
119→
120→    None
121→}
