 17→fn format_messages(
 18→    messages: &[message::SlackMessage],
 19→    user_names: &HashMap<String, String>,
 20→) -> String {
 21→    messages
 22→        .iter()
 23→        .map(|m| {
 24→            let display = match user_names.get(&m.user) {
 25→                Some(name) => format!("@{}", name),
 26→                None => m.user.clone(),
 27→            };
 28→            format!(
 29→                "{} {} {}",
 30→                message::format_unix_ts(&m.ts),
 31→                display,
 32→                m.text
 33→            )
 34→        })
 35→        .collect::<Vec<_>>()
 36→        .join("\n")
 37→}
