 39→fn resolve_user_names(
 40→    messages: &[message::SlackMessage],
 41→    token: &str,
 42→) -> HashMap<String, String> {
 43→    let unique_ids: std::collections::HashSet<&str> = messages
 44→        .iter()
 45→        .map(|m| m.user.as_str())
 46→        .filter(|id| id.starts_with('U'))
 47→        .collect();
 48→
 49→    let mut names = HashMap::new();
 50→    for id in unique_ids {
 51→        if let Ok(raw) = slack_api::fetch_user_info(id, token) {
 52→            if let Ok(json_val) = json::parse(&raw) {
 53→                if let Some(name) = message::resolve_user_name(&json_val) {
 54→                    names.insert(id.to_string(), name);
 55→                }
 56→            }
 57→        }
 58→    }
 59→    names
 60→}
