 62→fn run(args: Vec<String>) -> Result<String, SlkError> {
 63→    let url_str = parse_args(args)?;
 64→    let token = std::env::var("SLACK_TOKEN")
 65→        .map_err(|_| SlkError::from("SLACK_TOKEN environment variable is not set"))?;
 66→    let thread = url::parse_slack_url(&url_str)?;
 67→    let raw_json = slack_api::fetch_thread_replies(&thread.channel_id, &thread.ts, &token)?;
 68→    let json_value = json::parse(&raw_json)?;
 69→    let messages = message::extract_messages(&json_value)?;
 70→    let user_names = resolve_user_names(&messages, &token);
 71→    Ok(format_messages(&messages, &user_names))
 72→}
